import assert from "node:assert/strict";
import { Buffer } from "node:buffer";
import process from "node:process";
Object.assign(globalThis,{Buffer,process});
// Generated by the build step; never resolve to a second hand-maintained model.
const { adapter, registeredAdapters } = await import("./_generated/app/_lib/testAccounts/adapter.mjs");
const { unseal } = await import("./_generated/app/_lib/testAccounts/crypto.server.mjs");
const { directCustomerHandler } = await import("./_generated/app/_lib/testAccounts/directHandler.server.mjs");
const { runCleanupScope, assertAccountDatabaseAccess } = await import("./_generated/app/_lib/accountCleanupScope.server.mjs");
const fixtures=JSON.parse(await Deno.readTextFile(new URL("./_fixtures.json",import.meta.url)));
Object.assign(process.env,{ACCOUNT_PORTAL_ENABLED:"true",DIRECT_CUSTOMER_TESTS_ENABLED:"true",ACCOUNT_STORAGE_MODE:"active",TEST_ACCOUNTS_STORAGE_MODE:"active",TEST_ACCOUNTS_ENCRYPTION_KEY:Buffer.alloc(32,7).toString("base64url")});
const handler=directCustomerHandler();
function request(body: unknown,origin="https://www.relationsvarning.se") { return new Request("https://synthetic.supabase.co/functions/v1/customer-tests",{method:"POST",headers:{origin,"content-type":"application/json"},body:JSON.stringify(body)}); }
Deno.test("all 15 canonical engines load in Deno, 1200 report/crypto comparisons equal Node",()=>{
  assert.equal(registeredAdapters().length,15);
  for(const item of fixtures.cases) {
    const model=adapter(item.product);
    assert.deepEqual(model.calculate(model.parse(item.input)),item.result);
    assert.deepEqual(unseal(item.ciphertext,item.context),item.input);
  }
});
Deno.test("actual Edge handler fails closed by default, rejects outside origins and missing identity",async()=>{
  process.env.DIRECT_CUSTOMER_TESTS_ENABLED="false";
  assert.equal((await handler(request({action:"capabilities"}))).status,503);
  process.env.DIRECT_CUSTOMER_TESTS_ENABLED="true";
  assert.equal((await handler(request({action:"capabilities"},"https://attacker.invalid"))).status,403);
  assert.equal((await handler(request({action:"list",userId:"forged",paid:true}))).status,401);
  assert.equal((await handler(request({action:"legacy-import",paid:true}))).status,404);
});
Deno.test("all product flags are off unless explicitly enabled; no legacy checkout fallback",async()=>{
  const response=await handler(request({action:"capabilities"})),body=await response.json();
  assert.equal(response.status,200);assert.equal(body.tests.length,15);
  assert(body.tests.every((item:{checkout:boolean})=>item.checkout===false));
  assert.equal((await handler(request({action:"checkout",product:"audhd_test",payload:fixtures.cases[0].input,paid:true}))).status,503);
});
Deno.test("maintenance scope preserves job isolation under Deno async context",async()=>{
  process.env.ACCOUNT_PORTAL_ENABLED="false";
  assert.throws(()=>assertAccountDatabaseAccess("tests"));
  await runCleanupScope("tests",async()=>{await Promise.resolve();assert.doesNotThrow(()=>assertAccountDatabaseAccess("tests"));assert.throws(()=>assertAccountDatabaseAccess("audhd"));});
  assert.throws(()=>assertAccountDatabaseAccess("tests"));
  process.env.ACCOUNT_PORTAL_ENABLED="true";
});
Deno.test("runtime test has no permission to contact Vercel, Stripe, R2 or Supabase",async()=>{
  assert.equal((await Deno.permissions.query({name:"net"})).state,"denied");
});
Deno.test("actual Deno Stripe signature verification isolates new events and relays signed legacy bytes",async()=>{
  const {stripeClient}=await import("./_generated/app/_lib/testAccounts/payment.server.mjs");
  const {directStripeWebhook}=await import("./_generated/app/_lib/testAccounts/directWebhook.server.mjs");
  process.env.STRIPE_SECRET_KEY="sk_test_synthetic";
  process.env.STRIPE_WEBHOOK_SECRET="whsec_synthetic_not_real";
  process.env.DIRECT_CUSTOMER_TESTS_WEBHOOK_ENABLED="true";
  const stripe=stripeClient();let forwards=0;
  for(const isNew of [true,false]) {
    const raw=JSON.stringify({id:"evt_synthetic",type:"checkout.session.completed",data:{object:{metadata:isNew?{rv_flow:"direct_customer_v1"}:{}}}});
    const signature=await stripe.webhooks.generateTestHeaderStringAsync({payload:raw,secret:process.env.STRIPE_WEBHOOK_SECRET});
    const response=await directStripeWebhook(new Request("https://synthetic.supabase.co/functions/v1/customer-tests/stripe-webhook",{method:"POST",headers:{"stripe-signature":signature},body:raw}),stripe,async(_url,options)=>{
      forwards++;assert.equal(new TextDecoder().decode(options!.body as Uint8Array),raw);return new Response(null,{status:200});
    });
    assert.equal(response.status,200);assert.equal(forwards,isNew?0:1);
  }
});
